37	            missing.add("lastName");
38	        }
39	        if (normalizedAddress.isEmpty()) {
40	            missing.add("address");
41	        }
42	        if (isBlank(request.getCity())) {
43	            missing.add("city");
44	        }
45	        if (isBlank(request.getTelephone())) {
46	            missing.add("telephone");
47	        }
48	        if (!missing.isEmpty()) {
49	            throw new MissingOwnerFieldsException(missing);
50	        }
51	        request.setTelephone(TelephoneNormalizer.normalize(request.getTelephone()));
52	        request.setAddress(normalizedAddress);
53	        request.setEmail(normalizeEmail(request.getEmail()));
