1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.repository.OwnerRepository;
8	import org.springframework.samples.petclinic.rest.escalation.DailyOwnerLimitException;
9	
10	/**
11	 * Rejects a create-owner request once {@value #DAILY_LIMIT} or more owners have already been
12	 * registered today (by registrationDate), with a 429 Too Many Requests. Runs after
13	 * {@link BuildOwner} and before the owner is saved, so the count reflects only pre-existing
14	 * owners.
15	 */
16	public class CheckOwnerDailyLimit {
17	
18	    /** Maximum number of owners that may be created in a single day. */
19	    private static final int DAILY_LIMIT = 100;
20	
21	    public void service(@Val Owner owner, OwnerRepository ownerRepository)
22	            throws DailyOwnerLimitException {
23	        LocalDate today = LocalDate.now();
24	        int count = 0;
25	        for (Owner existing : ownerRepository.findAll()) {
26	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
27	                continue; // the owner being created is not counted against the limit
28	            }
29	            if (today.equals(existing.getRegistrationDate())) {
30	                count++;
31	            }
32	        }
33	        if (count >= DAILY_LIMIT) {
34	            throw new DailyOwnerLimitException(count);
35	        }
36	    }
37	}
