1	package org.springframework.samples.petclinic.rest.escalation;
2	
3	/**
4	 * Thrown when a create-owner request arrives after the maximum number of owners (100) have
5	 * already been registered today (by registrationDate). Handled as a 429 Too Many Requests.
6	 */
7	public class DailyOwnerLimitException extends Exception {
8	
9	    public DailyOwnerLimitException(int count) {
10	        super(count + " owners have already been created today; no further owners can be created "
11	                + "until tomorrow");
12	    }
13	}
